-- The recommended plans that ship in Data/Plans (generated by tools/gen_plans.lua from data-src/dungeons): every TOC
-- entry exists, every plan passes validation without losing anything, ids are unique, and no text carries a source or
-- licence remark. `lua tools/gen_plans.lua --check` (CI) covers that the files match the research data.
local T = ...
local ns = T.ns

-- The generated files the TOC lists.
local function tocSlugs()
	local slugs, seen = {}, {}
	for line in io.lines("DungeonPlanner.toc") do
		line = line:gsub("\r", "")
		local slug = line:match("^Data\\Plans\\(.+)%.lua$")
		if slug then
			T.ok(not seen[slug], "listed once: " .. slug)
			seen[slug] = true
			slugs[#slugs + 1] = slug
		end
	end
	return slugs
end

-- Runs one generated file against a stand-in Bundled.Add and returns the raw plan table it adds.
local function rawPlan(slug)
	local captured
	local chunk = assert(loadfile("Data/Plans/" .. slug .. ".lua"))
	chunk("DungeonPlanner", { Bundled = { Add = function(raw) captured = raw end } })
	return captured
end

local BLOCKED = { "needroll", "allthethings", "all the things", "openmap", "wowhead", "gpl", "licen", "sourced", "uimapid" }

local function everyString(value, fn)
	if type(value) == "string" then
		fn(value)
	elseif type(value) == "table" then
		for _, v in pairs(value) do
			everyString(v, fn)
		end
	end
end

T.case("Recommended plans: every TOC entry exists and is a plan with a matching id", function()
	local slugs = tocSlugs()
	T.ok(#slugs >= 1, "the TOC lists generated plans")
	for _, slug in ipairs(slugs) do
		local f = io.open("Data/Plans/" .. slug .. ".lua", "rb")
		T.ok(f, "file exists: " .. slug)
		local head = f:read(200)
		f:close()
		T.ok(head:find("GENERATED by tools/gen_plans.lua", 1, true), "marked as generated: " .. slug)
		local raw = rawPlan(slug)
		T.ok(raw, "adds a plan: " .. slug)
		T.eq(raw.id, slug, "plan id is the file name")
		T.ok(#raw.id <= 40 and raw.id:match("^[%w_%-]+$"), "id shape: " .. slug)
	end
end)

T.case("Recommended plans: every plan validates without losing a field, ids are unique", function()
	local ids = {}
	for _, slug in ipairs(tocSlugs()) do
		local raw = rawPlan(slug)
		T.ok(not ids[raw.id], "unique id " .. raw.id)
		ids[raw.id] = true
		local plan, report = ns.Validate.Plan(raw)
		T.ok(plan, "valid: " .. slug)
		T.eq(ns.Validate.Summary(report), nil, "nothing dropped from " .. slug)
		T.eq(#plan.markers, #raw.markers, "markers kept: " .. slug)
		T.eq(#plan.routes, #raw.routes, "routes kept: " .. slug)
		T.eq(#plan.pulls, #raw.pulls, "pulls kept: " .. slug)
		T.eq(#plan.encounters, #raw.encounters, "encounters kept: " .. slug)
		T.ok(plan.instance.name ~= "", "instance name: " .. slug)
		T.ok(plan.instance.origin == "forever" or plan.instance.origin == "classic", "instance origin: " .. slug)
		T.ok(plan.instance.levelMin and plan.instance.levelMax and plan.instance.levelMin <= plan.instance.levelMax, "levels: " .. slug)
		T.ok(plan.notes:find("approximate positions", 1, true) and plan.notes:find("Confidence: ", 1, true), "plan note: " .. slug)
		-- Text fields are within their limits as written (Validate cuts silently otherwise).
		T.eq(plan.notes, raw.notes, "notes kept whole: " .. slug)
		for i, m in ipairs(raw.markers) do
			T.eq(plan.markers[i].note, m.note or "", "marker note kept whole: " .. slug .. " " .. m.id)
		end
		-- Route points are numbered stops (1, 2, 3 ... in path order) or bare bends between them.
		for _, route in ipairs(plan.routes) do
			local n = 0
			for _, p in ipairs(route.points) do
				if p.step then
					n = n + 1
					T.eq(p.step, n, "stops numbered in order: " .. slug)
				else
					T.ok(p.note == nil and p.pull == nil, "a bend carries no note or pull: " .. slug)
				end
			end
			if route.optional and n == 0 then
				-- A side path (an imported route's way to an optional boss): bends only.
				T.ok(#route.points >= 2, "a side path has a line: " .. slug)
			else
				T.ok(n >= 1 and route.points[1].step and route.points[#route.points].step, "a route starts and ends at a stop: " .. slug)
			end
		end
	end
end)

-- data-src/routes/<slug>.json (tools/route_paths.py): the bends that keep a route on walkable floor.
T.case("Recommended plans: every route leg's bends are in the plan, between its two stops, on the map", function()
	local G = dofile("tools/gen_plans.lua")
	local legs, files = 0, 0
	local function at(p, xy)
		return G.Same(p[1], xy[1]) and G.Same(p[2], xy[2])
	end
	for _, slug in ipairs(tocSlugs()) do
		local f = io.open("data-src/routes/" .. slug .. ".json", "rb")
		if f then
			files = files + 1
			local doc = G.DecodeJSON(f:read("*a"))
			f:close()
			T.eq(doc.schema, 1, "routes schema: " .. slug)
			T.eq(doc.slug, slug, "routes file names its plan: " .. slug)
			local raw = rawPlan(slug)
			for _, leg in ipairs(doc.legs or {}) do
				legs = legs + 1
				local where = string.format("%s floor %d %s,%s", slug, leg.floor, leg.from[1], leg.from[2])
				local found = false
				for _, route in ipairs(raw.routes) do
					local pts = route.points
					for i = 1, #pts do
						if route.floor == leg.floor and pts[i].step and at(pts[i], leg.from) then
							local j = i + 1
							for _, b in ipairs(leg.bends) do
								T.ok(b[1] >= 0 and b[1] <= 1 and b[2] >= 0 and b[2] <= 1, "bend on the map: " .. where)
								T.ok(pts[j] and not pts[j].step and at(pts[j], b), "bend present in order: " .. where)
								j = j + 1
							end
							if pts[j] and pts[j].step and at(pts[j], leg.to) then
								found = true
							end
						end
					end
				end
				T.ok(found, "leg matches two consecutive stops of the plan: " .. where)
			end
			-- A moved point is no longer where it was.
			for _, m in ipairs(doc.moves or {}) do
				for _, marker in ipairs(raw.markers) do
					T.ok(not (marker.floor == m.floor and G.Same(marker.x, m.from[1]) and G.Same(marker.y, m.from[2])),
						"moved marker not left in the wall: " .. slug .. " " .. marker.id)
				end
			end
		end
	end
	T.ok(files >= 5 and legs >= 50, "routes data present (" .. files .. " files, " .. legs .. " legs)")
end)

-- data-src/routes/<slug>.json "import" (tools/import_routes.py): routes imported from Forever Dungeon Routes (MIT).
T.case("Imported routes: credited in each plan, on the map, off parchment and water, side paths optional, licence present", function()
	local G = dofile("tools/gen_plans.lua")
	local lic = io.open("docs/licenses/ForeverDungeonRoutes-LICENSE.txt", "rb")
	T.ok(lic, "its licence notice ships with the repository")
	local text = lic and lic:read("*a") or ""
	if lic then
		lic:close()
	end
	T.ok(text:find("MIT License", 1, true) and text:find("Copyright (c) 2026 Checkov23", 1, true), "MIT notice with its copyright")
	local function in01(x, y)
		return type(x) == "number" and type(y) == "number" and x >= 0 and x <= 1 and y >= 0 and y <= 1
	end
	local plans, legs, imported = 0, 0, {}
	for _, slug in ipairs(tocSlugs()) do
		local f = io.open("data-src/routes/" .. slug .. ".json", "rb")
		local doc = f and G.DecodeJSON(f:read("*a"))
		if f then
			f:close()
		end
		local imp = doc and doc["import"]
		if imp then
			plans = plans + 1
			local raw = rawPlan(slug)
			T.ok(imp.note:find("Forever Dungeon Routes (MIT)", 1, true), "credit line names it and its licence: " .. slug)
			T.ok(raw.notes:find(imp.note, 1, true), "the plan's notes carry the credit line: " .. slug)
			T.ok(imp.url:find("github.com/Checkov23/ForeverDungeonRoutes", 1, true), "where it comes from: " .. slug)
			if imp.from:lower():find("aetherflask", 1, true) then
				T.ok(type(imp.traced) == "string" and imp.traced:find("aetherflask", 1, true), "a traced route says so: " .. slug)
			end
			-- The parchment and water audit after the import: nothing it ships still runs over either.
			T.ok(type(imp.check) == "table" and imp.check.flagged == 0, "no stretch left over parchment or water: " .. slug)
			imported[slug] = true
			for _, e in ipairs(imp.fill) do
				T.ok(in01(e.at[1], e.at[2]) and e.floor >= 1 and e.floor <= #raw.floors, "placed point on the map: " .. slug)
			end
			for _, e in ipairs(imp.add) do
				T.ok(in01(e.at[1], e.at[2]) and e.floor >= 1 and e.floor <= #raw.floors, "added stop on the map: " .. slug)
				local found = false
				for _, r in ipairs(raw.routes) do
					for _, p in ipairs(r.points) do
						found = found or (r.floor == e.floor and p.step and G.Same(p[1], e.at[1]) and G.Same(p[2], e.at[2]))
					end
				end
				T.ok(found, "added stop is a numbered stop of the plan: " .. slug .. " " .. e.note)
			end
			for _, side in ipairs(imp.side) do
				local route
				for _, r in ipairs(raw.routes) do
					if r.optional and r.name == side.name and r.floor == side.floor then
						route = r
					end
				end
				T.ok(route, "side path is an optional route: " .. slug .. " " .. side.name)
				for _, p in ipairs(side.points) do
					T.ok(in01(p[1], p[2]), "side path on the map: " .. slug)
				end
			end
			for _, leg in ipairs(doc.legs) do
				if leg["import"] then
					legs = legs + 1
					for _, b in ipairs(leg.bends) do
						T.ok(in01(b[1], b[2]), "imported bend in range: " .. slug)
					end
				end
			end
		end
	end
	T.ok(plans >= 41 and legs >= 200, "imported routes present (" .. plans .. " plans, " .. legs .. " legs)")
	-- Every classic dungeon plan its routes cover (all but Scholomance, whose map in the client is a later layout).
	for _, slug in ipairs({ "blackfathom-deeps", "blackrock-depths", "dire-maul-east", "dire-maul-north", "dire-maul-west",
		"gnomeregan", "lower-blackrock-spire", "maraudon", "ragefire-chasm", "razorfen-downs", "razorfen-kraul",
		"scarlet-monastery-armory", "scarlet-monastery-cathedral", "scarlet-monastery-graveyard", "scarlet-monastery-library",
		"shadowfang-keep", "stratholme-live", "stratholme-undead", "temple-of-atalhakkar", "the-deadmines", "the-stockade",
		"uldaman", "upper-blackrock-spire", "wailing-caverns", "zulfarrak" }) do
		T.ok(imported[slug], "classic plan with its route and credit line: " .. slug)
	end
end)

T.case("Recommended plans: loaded into the addon, matched to their instance, no problems reported", function()
	local slugs = tocSlugs()
	local all = ns.Bundled.All()
	for _, slug in ipairs(slugs) do
		local plan = ns.Bundled.Get("b:" .. slug)
		T.ok(plan and plan.bundled, "loaded: " .. slug)
		T.ok(#ns.Bundled.ForInstance({ name = plan.instance.name }) >= 1, "matched by name: " .. slug)
		for _, problem in ipairs(ns.Bundled.problems) do
			T.ok(not problem:find("^" .. slug .. ":"), "no problem for " .. slug .. ": " .. problem)
		end
	end
	T.ok(#all >= #slugs)
end)

T.case("Recommended plans: no source, licence or researcher remark in any shipped text; positions carry their approx mark", function()
	for _, slug in ipairs(tocSlugs()) do
		local raw = rawPlan(slug)
		everyString(raw, function(s)
			local l = s:lower()
			for _, word in ipairs(BLOCKED) do
				T.ok(not l:find(word, 1, true), slug .. ": '" .. word .. "' in: " .. s:sub(1, 80))
			end
		end)
		for _, m in ipairs(raw.markers) do
			if m.kind == "position" then
				T.ok((m.note or ""):find("(approx.)", 1, true), "position marked approximate: " .. slug)
			end
			-- Only markers with real coordinates exist at all.
			T.ok(type(m.x) == "number" and type(m.y) == "number", "marker has coordinates: " .. slug)
		end
	end
end)
